using System.Text.Json;
using PhotoTrail.Windows;
static class MapWorkspaceChecks {
 public static void Run(){int n=0;void Check(bool v,string why){if(!v)throw new Exception(why);n++;}void Reject(Action a,string why){try{a();throw new Exception("accepted "+why);}catch(Exception e)when(e is IOException or InvalidDataException or ArgumentException or JsonException){Check(true,why);}}
 var root=Path.Combine(Environment.GetEnvironmentVariable("PHOTOTRAIL_TEST_OUTPUT")!,"favorites-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var path=Path.Combine(root,"workspace.json");var s=MapWorkspace.Read(path);Check(s.State.Favorites.Length==0&&!File.Exists(path),"readonly missing default");
 var value=new FavoriteLocation(Guid.NewGuid(),"手填地点","用户独立备注",new(121.48,31.23));s=MapWorkspace.Save(path,s,s.State with{Favorites=MapWorkspace.Upsert(s.State.Favorites,value)});var other=MapWorkspace.Read(path);s=MapWorkspace.Save(path,s,s.State with{Favorites=MapWorkspace.Upsert(s.State.Favorites,value with{Name="改名",Note="新备注"})});Check(s.State.Favorites.Single().Id==value.Id&&MapWorkspace.Read(path).State.Favorites.Single().Name=="改名","edit stable id restart");Reject(()=>MapWorkspace.Save(path,other,other.State),"stale multinstance refused");
 using(var gate=new FileStream(path+".guard",FileMode.Open,FileAccess.ReadWrite,FileShare.None))Reject(()=>MapWorkspace.Save(path,s,s.State),"crosssession lock refused");
 foreach(var p in new[]{new MapPoint(181,0),new MapPoint(0,-91),new MapPoint(double.NaN,0),new MapPoint(0,double.PositiveInfinity)})Reject(()=>MapWorkspace.Save(path,s,s.State with{Favorites=[value with{Point=p}]}),"invalid WGS84");
 Reject(()=>MapWorkspace.Save(path,s,s.State with{Favorites=[value,value]}),"duplicate id");Reject(()=>MapWorkspace.Save(path,s,s.State with{Favorites=[value with{Name=""}]}),"empty name");Reject(()=>MapWorkspace.Save(path,s,s.State with{GoogleLayer="imaginary"}),"layer allowlist");
 s=MapWorkspace.Save(path,s,s.State with{SelectedOnly=true,GoogleLayer="satellite",OpenView=new(10,20,8)});var restarted=MapWorkspace.Read(path);Check(restarted.State.SelectedOnly&&restarted.State.GoogleLayer=="satellite"&&restarted.State.OpenView==new MapViewport(10,20,8),"map preference restart");s=MapWorkspace.Save(path,s,s.State with{Favorites=[]});Check(MapWorkspace.Read(path).State.Favorites.Length==0,"explicit delete persist empty");File.WriteAllText(path,"invalid json");Reject(()=>MapWorkspace.Read(path),"corrupt read refused");Reject(()=>MapWorkspace.Save(path,s,s.State),"corrupt write refused");Check(File.ReadAllText(path)=="invalid json","corrupt bytes preserved");
 var good="{\"type\":\"view\",\"epoch\":2,\"longitude\":10,\"latitude\":20,\"zoom\":8}";Check(MapWorkspace.Message(MapMessage.Page,good,out _,out var epoch,out var view)&&epoch==2&&view==new MapViewport(10,20,8),"valid viewport");
 foreach(var source in new[]{"https://evil/",MapMessage.Page+"?x"})Check(!MapWorkspace.Message(source,good,out _,out _,out _),"origin refused");foreach(var bad in new[]{"{","[]",good.Replace("\"epoch\":2","\"epoch\":-1"),good.Replace("\"zoom\":8","\"zoom\":23"),good.Replace("\"longitude\":10","\"longitude\":181"),good.Replace("\"type\":\"view\"","\"type\":\"view\",\"type\":\"view\""),good.Replace("\"zoom\":8","\"zoom\":8,\"extra\":0"),good+new string(' ',1024)})Check(!MapWorkspace.Message(MapMessage.Page,bad,out _,out _,out _),"shape/bounds refused");
 Console.WriteLine($"{n} R09a favorite/storage/view boundary assertions passed without network.");
 }
}
